// M.A.S.K.: bond the masks on the selected tokens' actors to those actors (GM only) - after the lab work and downtime.
const api = game.modules.get('essence20-homebrew-starter')?.api?.mask;
if (!api) return ui.notifications.warn('Turn on the Essence20 Homebrew Starter module first.');
if (!game.user.isGM) return ui.notifications.warn('Only the GM rebonds masks.');
const actors = canvas.tokens.controlled.map(token => token.actor).filter(Boolean);
if (!actors.length) return ui.notifications.warn('Select the tokens of the agents whose masks to rebond.');
for (const actor of actors) {
  for (const mask of actor.items.filter(item => api.isMask(item) && !api.bondHolds(item, actor))) {
    await api.rebondMask(mask);
    ChatMessage.create({ content: `${mask.name} is now bonded to ${actor.name}.` });
  }
}
